/// <summary>
/// MPJ_17989 - kscerri - 12/14/2021
/// Tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METCustAuditReportTmp))]
public METCustAuditReportTmp getCustAuditReportTmp()
{
    select custAuditReportTmp;
    return custAuditReportTmp;
}

    /// <summary>
    /// MPJ_17989 Customer audit log - dcp 24/06/2022
    /// Process report data.
    /// </summary>
    public void processReport()
    {

        contract = this.parmDataContract() as METCustAuditReportContract;

        this.processCustTable();
        this.processMetCustTable();
        this.processDirPartyTable();
        this.processLogisticsElectronicAddress();
        this.processTaxRegistration();

    }

    /// <summary>
    /// MPJ_17989 Customer audit log - dcp 24/06/2022
    /// Process report data.
    /// </summary>
    public void processCustTable()
    {
        Query query = new Query(queryStr(METDBLogCustTable));

        query = this.updateQueryRanges(query);

        this.processTrans(query);
    }

    /// <summary>
    /// MPJ_17989 Customer audit log - dcp 24/06/2022
    /// Process report data.
    /// </summary>
    public void processMetCustTable()
    {
        Query query = new Query(queryStr(METDBLogMetCustTable));

        query = this.updateQueryRanges(query);

        this.processTrans(query);
    }

    /// <summary>
    /// MPJ_17989 Customer audit log - dcp 24/06/2022
    /// Process report data.
    /// </summary>
    public void processDirPartyTable()
    {
        Query query = new Query(queryStr(METDBLogDirPartyTable));

        query = this.updateQueryRanges(query);

        this.processTrans(query);
    }

    /// <summary>
    /// MPJ_17989 Customer audit log - dcp 24/06/2022
    /// Process report data.
    /// </summary>
    public void processLogisticsElectronicAddress()
    {
        Query query = new Query(queryStr(METDBLogLogisticsElectronicAddress));

        query = this.updateQueryRanges(query);

        this.processTrans(query);
    }

    /// <summary>
    /// MPJ_17989 Customer audit log - dcp 24/06/2022
    /// Process report data.
    /// </summary>
    public void processTaxRegistration()
    {
        Query query = new Query(queryStr(METDBLogTaxRegistration));

        query = this.updateQueryRanges(query);

        this.processTrans(query);
    }

    /// <summary>
    /// MPJ_17989 Customer audit log - dcp 24/06/2022
    /// Update query ranges
    /// </summary>
    /// <param name = "_query">Query</param>
    /// <returns>updated query</returns>
    public Query updateQueryRanges(Query _query)
    {
        Query query = _query;

        query = this.legalEntityRange(query);
        query = this.dateRange(query);
        query = this.accountNumRange(query);
        query  =this.custGroupRange(query);

        return query;
    }

    /// <summary>
    /// MPJ_17989 Customer audit log - dcp 24/06/2022
    /// Update query ranges
    /// </summary>
    /// <param name = "_query">Query</param>
    /// <returns>updated query</returns>
    public query legalEntityRange(Query _query)
    {
        Query           query = _query;
        List            legalEntityList = new List(Types::String);
        ListEnumerator  legalEntityListEnum;

        //Legal entity range
        legalEntityList     = contract.parmLegalEntity();
        legalEntityListEnum = legalEntityList.getEnumerator();
        
        query.allowCrossCompany(true);
        query.addCompanyRange(METConstants::datLegalEntityId);

        while (legalEntityListEnum.moveNext())
        {
            query.addCompanyRange(legalEntityListEnum.current());
        }

        return query;
    }

    /// <summary>
    /// MPJ_17989 Customer audit log - dcp 24/06/2022
    /// Update query ranges
    /// </summary>
    /// <param name = "_query">Query</param>
    /// <returns>updated query</returns>
    public Query dateRange(Query _query)
    {
        // Date range
        Query                   query = _query;
        QueryBuildDataSource    qbds;
        QueryBuildRange         qbr;

        qbds = query.dataSourceTable(tableNum(SysDataBaseLog));

        if(qbds)
        {
            qbr = SysQuery::findOrCreateRange(qbds, fieldNum(SysDataBaseLog, CreatedDateTime));

            if(qbr)
            {
                qbr.value(queryRange(contract.parmFromDateChange(), contract.parmToDateChange()));
            }
            
        }
        return query;
    }

    /// <summary>
    /// MPJ_17989 Customer audit log - dcp 24/06/2022
    /// Update query ranges
    /// </summary>
    /// <param name = "_query">Query</param>
    /// <returns>updated query</returns>
    public Query accountNumRange(Query _query)
    {
        // Customer range
        Query                   query = _query;
        QueryBuildDataSource    qbds;

        List                    custAccountList = new List(Types::String);
        ListEnumerator          custAccountListEnum;

        qbds = query.dataSourceTable(tableNum(CustTable));

        if(qbds)
        {
            custAccountList     = contract.parmCustAccount();
            custAccountListEnum = custAccountList.getEnumerator();
            
            while (custAccountListEnum.moveNext())
            {
                qbds.addRange(fieldNum(Custtable, accountNum)).value(CustAccountListEnum.current());
            }
        }
        return query;
    }

    /// <summary>
    /// MPJ_17989 Customer audit log - dcp 24/06/2022
    /// Update query ranges
    /// </summary>
    /// <param name = "_query">Query</param>
    /// <returns>updated query</returns>
    public Query custGroupRange(Query _query)
    {
        // Customer range
        Query                   query = _query;
        QueryBuildDataSource    qbds;

        List                    custGroupList = new List(Types::String);
        ListEnumerator          custGrouplistEnum;

        qbds = query.dataSourceTable(tableNum(CustTable));

        if(qbds)
        {
            custGroupList     = contract.parmCustGroup();
            custGrouplistEnum = custGroupList.getEnumerator();
            
            while (custGrouplistEnum.moveNext())
            {
                qbds.addRange(fieldNum(CustTable, custGroup)).value(custGrouplistEnum.current());
            }
        }
        return query;
    }

    /// <summary>
    /// MPJ_17989 Customer audit log - dcp 24/06/2022
    /// Update query ranges
    /// </summary>
    /// <param name = "_query">Query</param>
    public void processTrans(Query _query)
    {
        QueryRun            queryRun;
        SysDataBaseLog      sysDataBaseLog;
        CustTable           custTable;
        DirPartyTable       dirPartyTable;
        List                list = new List(Types::Container);
        ListEnumerator      listEnumerator;
        container           change;
        System.String       fieldString;
        System.Object       newValue;
        System.Object       oldValue;

        if (_query)
        {
            queryRun = new QueryRun(_query);
            
            while (queryRun.next())
            {
                recordFound = true;
                
                sysDataBaseLog  = queryRun.get(tableNum(SysDataBaseLog));
                custTable       = queryRun.get(tableNum(CustTable));
                dirPartyTable   = queryRun.get(tableNum(DirPartyTable));

                list            = sysDataBaseLog.getDataAslist();
                listEnumerator  = list.getEnumerator();
                
                while (listEnumerator.moveNext())
                {
                    change = listEnumerator.current();
                    [fieldString, newValue, oldValue] = change;

                    if (fieldId2Name(sysDataBaseLog.table, str2int(fieldString)) != fieldStr(CustTable, ModifiedDateTime) &&
                        fieldId2Name(sysDataBaseLog.table, str2int(fieldString)) != fieldStr(CustTable, ModifiedBy))
                    {
                        ttsbegin;

                        custAuditReportTmp.AccountNum           = custTable.AccountNum;
                        custAuditReportTmp.CustName             = dirPartyTable.Name;
                        custAuditReportTmp.DateOfChange         = sysDataBaseLog.CreatedDateTime;
                        custAuditReportTmp.LegalEntity          = custTable.DataAreaId;
                        custAuditReportTmp.NewChange            = METNewChange::Change;
                        custAuditReportTmp.TableName            = tableId2Name(sysDataBaseLog.table);
                        custAuditReportTmp.UserIdCreatedBy      = sysDataBaseLog.CreatedBy;
                        custAuditReportTmp.Field                = fieldId2Name(sysDataBaseLog.table, str2int(fieldString));
                        custAuditReportTmp.NewValue             = newValue;
                        custAuditReportTmp.OldValue             = oldValue;

                        custAuditReportTmp.insert();

                        ttscommit;
                    }
                }
            }

            if(!recordFound)
            {
                warning ("@MET:VendAuditReportWarning");
            }
        }
    }
